"""Render measured research results after verification; never chooses endpoints."""
import csv,json,subprocess
from pathlib import Path
import numpy as np
B=Path('reports/evidence/v1_finish/m005b')
def read(p):return json.loads(Path(p).read_text())
def number(v,d=4):return f'{v:.{d}f}'
def estimate(z):return f"{z['mean']:.4f} [{z['ci95'][0]:.4f}, {z['ci95'][1]:.4f}]"
def generate():
 assert read(B/'development_finished.json')['status']=='COMPLETE';s=read(B/'analysis_primary/summary.json');v=read(B/'primary_verification.json');iv=read(B/'primary_metrics_verification.json');assert v['status']==iv['status']=='PASS';pc=read(B/'primary_closure.json');fc=read(B/'faults_closure.json');com=read(B/'figures_primary/computation.json');resource=read('reports/evidence/v1_finish/resource_readiness.json');rev=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip();launch=read(B/'primary_launch.json');rows=list(csv.DictReader((B/'analysis_primary/trial_metrics.csv').open()));valid=read(B/'development_finished.json')['validation_permitted'];validation='Development gates passed; validation must be completed and independently verified before full adaptive scientific qualification.' if valid and not (B/'validation_finished.json').exists() else 'Validation not opened: development mandatory scientific gates failed.' if not valid else 'See separately verified validation evidence.'
 lines=['# M005B adaptive-control evaluation — Operation V1 Finish','',f"Development execution PASS; development adaptive scientific {'PASS' if s['scientific_pass'] else 'FAIL'}. {validation} Locked100–119 remain unopened.",'','## Source, preservation and design','',f'Starting Operation V1 revision fa8f0a71c29b15678bc6cb872d88eda49ab5c81a. Review branch codex/v1-finish. Neural acquisition source {launch["source_revision"]}. Reporting source before final evidence commit {rev}; final handoff supplies the exact containing revision. Historical M005B.2 readiness HOLD, M005A.5 FAIL and all earlier outcomes remain unchanged. No merge, tag or publication.','', 'Protocol011 is unchanged:20development trials, networks0–9, noise47/48,13matched64s branches/trial after51s calibration. STATIC and LOSS×sixmethods, plus LOSS_MAX. Secondary faults: networks0–2/noise49,8branches/trial. PI10/5 remains frozen. No hyperparameter selection. Raw1s E80 rate is scored; loss at16s; primary error includes all48post-loss seconds. Three workers; original10800s development cap includes faults.','', '## Primary paired inference','', 'Each entry is network-mean effect [paired whole-network95%interval]. Repeats average within network first;10000PCG64seed20261105resamples. Relative effect is mean within-network ratio, not ratio of cohort means.','', '| Comparison | Absolute IAE reduction (Hz s) | Relative reduction | Positive networks | Gate |','|---|---:|---:|---:|---|']
 for label,key in [('RLS versus PI','H1a'),('RLS versus fixed MPC','H1b')]:
  z=s[key];lines.append(f"| {label} | {estimate(z['absolute'])} | {estimate(z['relative'])} | {z['positive_networks']}/10 | {z['decision']} |")
 lines+=['','Required H1a floors:10%,1.2Hz s,positiveCIand8/10. H1b:5%,.6Hz s,positiveCIand8/10. Both are mandatory.','', '| Regime/controller | Post-loss-window IAE (Hz s) | Late bias (Hz) | Late MAE (Hz) | Calibration+control exposure (pA s) |','|---|---:|---:|---:|---:|']
 for reg in ('STATIC','LOSS'):
  for kind in ('PI10_5','FIXED-MPC','RLS-MPC','BIAS-MPC','FIXED','ZERO'):
   z=s['models'][reg+'_'+kind];lines.append(f"| {reg}/{kind} | {estimate(z['post_iae_hz_s'])} | {estimate(z['late_bias_hz'])} | {estimate(z['late_mae_hz'])} | {estimate(z['total_exposure_pA_s'])} |")
 lines+=['','STATIC column uses the same16–64s descriptive window; its stationary guard uses the full0–64s.','', '## All development networks','', '| Network | PI loss IAE | Fixed MPC loss IAE | RLS loss IAE | Bias MPC loss IAE | RLS late loss bias | RLS post-loss exposure |','|---|---:|---:|---:|---:|---:|---:|']
 for n in range(10):
  def val(kind,key):return np.mean([float(r[key]) for r in rows if int(r['network'])==n and r['condition']=='LOSS' and r['controller']==kind])
  lines.append('| '+str(n)+' | '+' | '.join(number(val(k,key)) for k,key in [('PI10_5','post_iae_hz_s'),('FIXED-MPC','post_iae_hz_s'),('RLS-MPC','post_iae_hz_s'),('BIAS-MPC','post_iae_hz_s'),('RLS-MPC','late_bias_hz'),('RLS-MPC','post_exposure_pA_s')])+' |')
 lines+=['','Every replicate/branch is retained in analysis_primary/trial_metrics.csv and every1s outcome in timecourses.csv. No network exclusion or seed replacement.','', '## Guardrails and secondary outcomes','', '| Gate | Result | Detail |','|---|---|---|',f"| H2 persistent recovery benefit | {s['H2']['pass_gate']} | {estimate(s['H2']['absolute'])} s; {s['H2']['positive_networks']}/10 positive |"]
 for reg in ('STATIC','LOSS'):
  for kind in ('PI10_5','FIXED-MPC','RLS-MPC'):
   z=s['H3'][reg+'_'+kind];lines.append(f"| H3 {reg}/{kind} | {z['pass_gate']} | {z['qualified']}/10 qualified; bias {estimate(z['bias'])} Hz |")
  z=s['H4'][reg];lines.append(f"| H4 dose {reg} | {z['pass_gate']} | {estimate(z['ratio']) if z['ratio'] else 'undefined ratio'} |")
  z=s['H5'][reg];lines.append(f"| H5 {reg} | {z['pass_gate']} | relative harm {estimate(z['relative_harm'])} |")
 lines+=[f"| Safety | {s['safety_pass']} | All constraints, model/fallback events retained |",'', 'H3 requires substantive1Hz/noise/headroom/late-bias/MAE conditions. H4/H5 prevent buying benefit with excessive dose or stationary harm. Detailed calibration, block windows, MAX headroom, saturation and per-network failure components are in the qualification table. H2 is finite-horizon retrospective persistence, not mathematical stability or an online detector.','', '## Independent verification','', f"Raw verifier: {v['trials']}trials,{v['branches']}branches,{v['bins']}bins,{v['model_hashes']}model hashes,{v['candidate_scores']}candidate scores; violations={v['violations']},fallback_bins={v['fallback_bins']}. Independent raw-target/statistical checks={iv['raw_metric_checks']}; primary gates exactly reproduced. Independent weighted batch normal equations and scalar PI recurrence supplement exact codec replay. Secondary fault verification and shadow models are separate and cannot rescue gates.",'', '## Costs and computation','', f"Primary wall {pc['elapsed_s']:.3f}s; secondary fault wall {fc['elapsed_s']:.3f}s. Both share the original development deadline. Forecast including15%margin {resource['development_with_margin_s']:.3f}s; forecast is not an observed benchmark. Native-clock/resource samples retain actual polling cadence and peakRSS. No physical-sleep test or hard real-time claim.",'', '| Controller | Decision command p50/p95/p99/max (ms) | Update p50/p95/p99/max (ms) | Planner p50/p95/p99/max (ms) | Safe bins |','|---|---|---|---|---:|']
 for kind,z in com['controllers'].items():
  def times(key):
   a=z[key];return '/'.join(f'{a[k]:.3f}' for k in ('p50','p95','p99','maximum')) if a else 'n/a'
  lines.append(f"| {kind} | {times('command_ms')} | {times('update_ms')} | {times('planner_ms')} | {z['fallback_bins']} |")
 lines+=['', 'Prediction accuracy and frozen-on-same-input comparisons are in model_diagnostics.json. Weak-excitation FIXED/ZERO shadows and shuffled-fit control are in shadows/summary.json; they do not establish alternative realized control. BIAS-MPC is the required intercept-only mechanism ablation. Coefficient changes are not physical gain identification.','', '## Figures','', '![Tracking and cumulative error](evidence/v1_finish/m005b/figures_primary/tracking_and_cumulative.png)','', '![Network outcomes and cost](evidence/v1_finish/m005b/figures_primary/network_and_cost.png)','', '## Interpretation and next falsifiable step','', 'Adaptive scientific success requires the conjunction, not a favorable isolated metric. If any mandatory gate fails, preserve frozen PI/fixed-model results and do not retune on these outcomes. Closed-loop weak excitation, baseline compensation, surrogate error and actuator limits are distinct explanations; these data alone do not identify their causal contributions. No biological, plasticity or intelligence claim follows.','', 'Before a new adaptive study, prospectively test whether an explicitly budgeted identification intervention produces transferable held-out response prediction under closed-loop excitation, with stationary cost guards and competitive intercept-only/reference models. Any controller redesign requires a new frozen protocol; locked testing is not authorized by this report.','', '## Reproduction','', 'See docs/V1_REPRODUCIBILITY.md, the committed analysis scripts and all launch/supervision records. Exact commands and deadline identities are retained in those records. Scientific source/configuration/SeedSequence roles and immutable historical hash manifest are preserved.']
 Path('reports/M005B_V1_ADAPTIVE_CONTROL.md').write_text('\n'.join(lines)+'\n')
if __name__=='__main__':generate()
